import { useState } from "react";

export function ChatRoom({ messages }: { messages: Message[] }) {
  const [draft, setDraft] = useState("");

  return (
    <section>
      {/* Same array every time, yet it renders on every keystroke */}
      <MessageList messages={messages} />
      <textarea value={draft} onChange={(e) => setDraft(e.target.value)} />
      <button onClick={() => send(draft)}>Send</button>
    </section>
  );
}

import { useState } from "react";

// The draft lives in the only component that reads it
function Composer() {
  const [draft, setDraft] = useState("");
  return (
    <>
      <textarea value={draft} onChange={(e) => setDraft(e.target.value)} />
      <button onClick={() => send(draft)}>Send</button>
    </>
  );
}

export function ChatRoom({ messages }: { messages: Message[] }) {
  return (
    <section>
      <MessageList messages={messages} />
      <Composer />
    </section>
  );
}

