import { createContext, memo, useContext, useState } from "react";

const PrefsContext = createContext({ compact: false });

const Header = memo(function Header({ title }: { title: string }) {
  const prefs = useContext(PrefsContext);
  console.log("Header render"); // logs on every keystroke, memo or not
  return <h1 className={prefs.compact ? "small" : "large"}>{title}</h1>;
});

export function ChatRoom() {
  const [draft, setDraft] = useState("");
  return (
    // A new object on every render: Object.is reports a changed context
    <PrefsContext value={{ compact: true }}>
      <Header title="Support" />
      <textarea value={draft} onChange={(e) => setDraft(e.target.value)} />
    </PrefsContext>
  );
}
